package com.bella;

import java.math.BigDecimal;
import java.nio.file.*;
import java.security.SecureRandom;
import java.security.MessageDigest;
import java.io.*;
import javax.imageio.ImageIO;
import java.time.OffsetDateTime;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.*;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.servlet.config.annotation.*;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import jakarta.servlet.http.*;

@SpringBootApplication @EnableScheduling
public class BellaApplication {
 public static void main(String[] args){SpringApplication.run(BellaApplication.class,args);}
 @Bean BCryptPasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain apiSecurity(HttpSecurity http) throws Exception{return http.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).httpBasic(b->b.disable()).formLogin(f->f.disable()).build();}
 @Bean WebMvcConfigurer cors(@Value("${bella.cors-origin}") String origin){return new WebMvcConfigurer(){public void addCorsMappings(CorsRegistry registry){registry.addMapping("/api/**").allowedOrigins(origin).allowedMethods("GET","POST","OPTIONS").allowedHeaders("Content-Type","X-CSRF-Token").allowCredentials(true);}};}
 @Bean CommandLineRunner adminSeed(JdbcTemplate db,BCryptPasswordEncoder encoder,@Value("${bella.admin.username:}") String user,@Value("${bella.admin.password:}") String pass){return args->{if(!user.isBlank()&&!pass.isBlank()){db.update("INSERT INTO admins(username,email,password_hash) VALUES(?,?,?) ON CONFLICT(username) DO NOTHING",user,user+"@bella.invalid",encoder.encode(pass));}};}
 @RestController @RequestMapping("/api")
 static class Api {
  final JdbcTemplate db; final BCryptPasswordEncoder encoder; final Path storage; final SecureRandom random=new SecureRandom();
  Api(JdbcTemplate db,BCryptPasswordEncoder encoder,@Value("${bella.storage-path}") String storage){this.db=db;this.encoder=encoder;this.storage=Path.of(storage).toAbsolutePath().normalize();}
  Map<String,Object> ok(Object data){return Map.of("success",true,"data",data);}
  Map<String,Object> fail(String message){return Map.of("success",false,"message",message);}
  String verifyReceipt(MultipartFile file){try{byte[] b=file.getBytes();if(b.length>=5&&new String(b,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-"))return "pdf";if(b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255)return "jpg";if(b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return "png";throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"Only valid JPG, PNG and PDF receipts are allowed");}catch(IOException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unable to read receipt");}}
  @Scheduled(fixedDelayString="${bella.reservation-cleanup-ms:60000}") @Transactional public void expireReservations(){var expired=db.queryForList("SELECT id FROM orders WHERE order_status='PENDING_PAYMENT' AND stock_reserved=true AND reservation_expires_at<=now() AND NOT EXISTS(SELECT 1 FROM payments WHERE payments.order_id=orders.id)");for(var row:expired){long id=((Number)row.get("id")).longValue();var items=db.queryForList("SELECT product_id,quantity FROM order_items WHERE order_id=?",id);for(var item:items)db.update("UPDATE products SET stock_quantity=stock_quantity+?,updated_at=now() WHERE id=?",item.get("quantity"),item.get("product_id"));db.update("UPDATE orders SET order_status='CANCELLED',stock_reserved=false,reservation_expires_at=NULL,updated_at=now() WHERE id=? AND order_status='PENDING_PAYMENT' AND stock_reserved=true",id);}}
  void csrf(HttpServletRequest req){HttpSession s=req.getSession(false);String expected=s==null?null:(String)s.getAttribute("csrf");if(expected==null||!MessageDigestSupport.equal(expected,req.getHeader("X-CSRF-Token")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"CSRF validation failed");}
  void admin(HttpServletRequest req){HttpSession s=req.getSession(false);if(s==null||s.getAttribute("admin")==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required");}
  String verifyProductImage(MultipartFile file){try{byte[] b=file.getBytes();if(b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255)return "jpg";if(b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71&&b[4]==13&&b[5]==10&&b[6]==26&&b[7]==10)return "png";if(b.length>=12&&new String(b,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF")&&new String(b,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP"))return "webp";throw new ResponseStatusException(HttpStatus.UNSUPPORTED_MEDIA_TYPE,"Use a valid JPG, PNG, or WebP image");}catch(IOException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unable to read product image");}}
  @GetMapping("/products") Map<String,Object> products(){return ok(db.queryForList("SELECT id,name,description,price,image,stock_quantity FROM products WHERE is_active=true ORDER BY created_at DESC,id DESC"));}
  record OrderInput(String customer_name,String phone,String address,long product_id,int quantity){}
  @PostMapping("/orders") @Transactional Map<String,Object> create(@RequestBody OrderInput in){if(in.customer_name()==null||in.customer_name().isBlank()||in.customer_name().length()>150||in.phone()==null||!in.phone().matches("01[0125][0-9]{8}")||in.address()==null||in.address().isBlank()||in.address().length()>2000||in.quantity()<1||in.quantity()>100)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Check customer, phone, address, and quantity");var p=db.query("SELECT id,name,price,stock_quantity FROM products WHERE id=? AND is_active FOR UPDATE",(r,n)->Map.of("id",r.getLong("id"),"name",r.getString("name"),"price",r.getBigDecimal("price"),"stock",r.getInt("stock_quantity")),in.product_id()).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if((int)p.get("stock")<in.quantity())throw new ResponseStatusException(HttpStatus.CONFLICT,"Insufficient stock");BigDecimal price=(BigDecimal)p.get("price"),total=price.multiply(BigDecimal.valueOf(in.quantity()));String number="BELLA-"+String.format("%08X",random.nextInt());db.update("UPDATE products SET stock_quantity=stock_quantity-?,updated_at=now() WHERE id=?",in.quantity(),in.product_id());Long id=db.queryForObject("INSERT INTO orders(order_number,customer_name,phone,address,total_amount,order_status,reservation_expires_at,stock_reserved) VALUES(?,?,?,?,?,'PENDING_PAYMENT',now()+interval '30 minutes',true) RETURNING id",Long.class,number,in.customer_name().trim(),in.phone(),in.address().trim(),total);db.update("INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,subtotal) VALUES(?,?,?,?,?,?)",id,in.product_id(),p.get("name"),price,in.quantity(),total);return ok(Map.of("order_id",id,"order_number",number,"total_amount",total));}
  @PostMapping("/orders/status") Map<String,Object> orderStatus(@RequestBody Map<String,String> in){if(in.getOrDefault("order_number","").matches("(?i)BELLA-[A-F0-9]{8}")&&in.getOrDefault("phone","").matches("01[0125][0-9]{8}")){var rows=db.queryForList("SELECT order_number,total_amount,order_status,created_at FROM orders WHERE order_number=? AND phone=?",in.get("order_number").toUpperCase(),in.get("phone"));if(!rows.isEmpty())return ok(rows.get(0));}throw new ResponseStatusException(HttpStatus.NOT_FOUND,"We could not find an order matching those details");}
  @PostMapping("/payments") @Transactional Map<String,Object> payment(@RequestParam long order_id,@RequestParam String payment_method,@RequestParam(required=false) String transaction_reference,@RequestParam MultipartFile receipt){if(!Set.of("INSTAPAY","ORANGE_CASH").contains(payment_method)||receipt.isEmpty()||receipt.getSize()>3*1024*1024||(transaction_reference!=null&&transaction_reference.length()>150))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Select a valid payment method, reference, and receipt up to 3 MB");String ext=verifyReceipt(receipt);var o=db.queryForList("SELECT * FROM orders WHERE id=? FOR UPDATE",order_id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found"));if(!"PENDING_PAYMENT".equals(o.get("order_status"))||!Boolean.TRUE.equals(o.get("stock_reserved"))||o.get("reservation_expires_at")==null||((OffsetDateTime)o.get("reservation_expires_at")).isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Order reservation is no longer valid");if(!db.queryForList("SELECT id FROM payments WHERE order_id=? AND payment_status IN ('PENDING','PAID')",order_id).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"A pending or completed payment already exists for this order");try{Path dir=storage.resolve("receipts");Files.createDirectories(dir);String name=UUID.randomUUID()+"."+ext;receipt.transferTo(dir.resolve(name));Long id=db.queryForObject("INSERT INTO payments(order_id,payment_method,amount,transaction_reference,receipt_path) VALUES(?,?,?,?,?) RETURNING id",Long.class,order_id,payment_method,o.get("total_amount"),transaction_reference,"receipts/"+name);db.update("UPDATE orders SET reservation_expires_at=NULL WHERE id=?",order_id);return ok(Map.of("payment_id",id,"order_id",order_id,"amount",o.get("total_amount"),"payment_status","PENDING"));}catch(Exception e){throw new ResponseStatusException(HttpStatus.INTERNAL_SERVER_ERROR,"Unable to save receipt");}}
  @PostMapping("/admin/login") Map<String,Object> login(@RequestBody Map<String,String> in,HttpServletRequest req){var rows=db.queryForList("SELECT id,username,password_hash FROM admins WHERE username=?",in.getOrDefault("username",""));if(rows.isEmpty()||!encoder.matches(in.getOrDefault("password",""),(String)rows.get(0).get("password_hash")))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password");HttpSession existing=req.getSession(false);if(existing!=null)existing.invalidate();HttpSession s=req.getSession(true);s.setAttribute("admin",rows.get(0).get("id"));s.setAttribute("username",rows.get(0).get("username"));s.setAttribute("csrf",UUID.randomUUID().toString());return ok(Map.of("admin_id",s.getAttribute("admin"),"username",s.getAttribute("username"),"csrf_token",s.getAttribute("csrf")));}
  @GetMapping("/admin/session") Map<String,Object> session(HttpServletRequest req){admin(req);HttpSession s=req.getSession();return ok(Map.of("admin_id",s.getAttribute("admin"),"username",s.getAttribute("username"),"csrf_token",s.getAttribute("csrf")));}
  @PostMapping("/admin/logout") Map<String,Object> logout(HttpServletRequest req){admin(req);csrf(req);req.getSession().invalidate();return ok(Map.of());}
  @GetMapping("/admin/payments") Map<String,Object> pending(HttpServletRequest req){admin(req);return ok(db.queryForList("SELECT p.id AS payment_id,p.order_id,p.payment_method,p.amount,p.transaction_reference,p.payment_status,p.created_at AS payment_created_at,(p.receipt_path IS NOT NULL) AS receipt_available,o.order_number,o.customer_name,o.phone,o.address,o.total_amount,o.order_status FROM payments p JOIN orders o ON o.id=p.order_id WHERE p.payment_status='PENDING' ORDER BY p.created_at,p.id"));}
  @GetMapping("/admin/payments/{id}/receipt") ResponseEntity<byte[]> receipt(@PathVariable long id,HttpServletRequest req){admin(req);String rel=db.query("SELECT receipt_path FROM payments WHERE id=?",r->r.next()?r.getString(1):null,id);if(rel==null||!rel.matches("receipts/[a-f0-9-]+\\.(jpg|png|pdf)"))throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{Path file=storage.resolve(rel).normalize();if(!file.startsWith(storage)||!Files.isRegularFile(file))throw new ResponseStatusException(HttpStatus.NOT_FOUND);String type=rel.endsWith("pdf")?"application/pdf":rel.endsWith("png")?"image/png":"image/jpeg";return ResponseEntity.ok().header(HttpHeaders.CONTENT_TYPE,type).header("Cache-Control","private,no-store").header("X-Content-Type-Options","nosniff").body(Files.readAllBytes(file));}catch(java.io.IOException e){throw new ResponseStatusException(HttpStatus.NOT_FOUND);}}
  @PostMapping("/admin/payments/{id}/review") @Transactional Map<String,Object> review(@PathVariable long id,@RequestBody Map<String,String> in,HttpServletRequest req){admin(req);csrf(req);var p=db.queryForList("SELECT p.*,o.order_status,o.stock_reserved,o.total_amount FROM payments p JOIN orders o ON o.id=p.order_id WHERE p.id=? FOR UPDATE OF p,o",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found"));if(!"PENDING".equals(p.get("payment_status"))||!"PENDING_PAYMENT".equals(p.get("order_status"))||!Boolean.TRUE.equals(p.get("stock_reserved")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Payment or order cannot be reviewed");boolean approve="approve".equals(in.get("decision"));if(!approve&& !"reject".equals(in.get("decision")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid decision");db.update("UPDATE payments SET payment_status=?,admin_note=?,reviewed_at=now(),updated_at=now() WHERE id=?",approve?"PAID":"REJECTED",in.get("admin_note"),id);db.update("UPDATE orders SET order_status=?,stock_reserved=?,reservation_expires_at=NULL,updated_at=now() WHERE id=?",approve?"PROCESSING":"PENDING_PAYMENT",approve,(long)p.get("order_id"));return ok(Map.of("payment_id",id,"payment_status",approve?"PAID":"REJECTED"));}
  @GetMapping("/admin/orders") Map<String,Object> orders(@RequestParam(defaultValue="50") int limit,@RequestParam(defaultValue="0") int offset,HttpServletRequest req){admin(req);limit=Math.max(1,Math.min(100,limit));offset=Math.max(0,offset);var list=db.queryForList("SELECT o.*,string_agg(oi.product_name||' x'||oi.quantity,', ' ORDER BY oi.id) AS items_summary FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY o.created_at DESC,o.id DESC LIMIT ? OFFSET ?",limit,offset);int count=Optional.ofNullable(db.queryForObject("SELECT count(*) FROM orders",Integer.class)).orElse(0);return ok(Map.of("orders",list,"pagination",Map.of("limit",limit,"offset",offset,"total",count,"has_more",offset+list.size()<count)));}
  @PostMapping("/admin/orders/{id}/cancel") @Transactional Map<String,Object> cancel(@PathVariable long id,HttpServletRequest req){admin(req);csrf(req);var rows=db.queryForList("SELECT * FROM orders WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Order not found");var o=rows.get(0);if(!"PENDING_PAYMENT".equals(o.get("order_status"))||!Boolean.TRUE.equals(o.get("stock_reserved")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Order cannot be cancelled");if(!db.queryForList("SELECT id FROM payments WHERE order_id=?",id).isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Order with payment record requires payment review");for(var item:db.queryForList("SELECT product_id,quantity FROM order_items WHERE order_id=?",id))db.update("UPDATE products SET stock_quantity=stock_quantity+?,updated_at=now() WHERE id=?",item.get("quantity"),item.get("product_id"));db.update("UPDATE orders SET order_status='CANCELLED',stock_reserved=false,reservation_expires_at=NULL,updated_at=now() WHERE id=?",id);return ok(Map.of("order_id",id,"order_status","CANCELLED"));}
 }
}
class MessageDigestSupport {static boolean equal(String a,String b){return b!=null&&java.security.MessageDigest.isEqual(a.getBytes(java.nio.charset.StandardCharsets.UTF_8),b.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
